// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes CountryChanges) Audit(policy CountryAuditPolicy) (record.Model[Country, CountryCode], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Country, CountryCode]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Country, CountryCode]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "code", policy.Code)
	if err != nil {
		return record.Model[Country, CountryCode]{}, err
	}
	var captured record.Field[Country]
	captured, err = record.CaptureField[Country]("code", codec.String[CountryCode](), changes.fields.Code, policy.Code)
	if err != nil {
		return record.Model[Country, CountryCode]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Country, CountryCode]{}, err
	}
	captured, err = record.CaptureField[Country]("name", codec.String[string](), changes.fields.Name, policy.Name)
	if err != nil {
		return record.Model[Country, CountryCode]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Country, CountryCode]{}, err
	}
	return builder.Build()
}

